function SweepQuestRewardsDialog:RefreshUI()
    self:RefreshPlayerInfo()
    self:FillSelf()
end
--- 刷新玩家信息
function SweepQuestRewardsDialog:RefreshPlayerInfo()
    local parameters = self.controller.Argument.parameters
    local playerLv = checkInt(parameters.playerLv)
    local CardConfMgr = CardConfMgr:GetInstance()
    local playerExp = CardConfMgr:GetPlayerExpByLevelId(playerLv)
    local nextExp = CardConfMgr:GetPlayerExpByLevelId(playerLv+1)
    local currentExp = checkInt(parameters.mainExp) - checkInt(playerExp.totalExp)
    local endAmount = currentExp / checkInt(nextExp.exp)
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = playerComponent.playerDojo
    local currentLevel = checkInt(playerDojo.level)
    local startAmount = 0
    if playerLv == currentLevel then
        startAmount = (checkInt(playerDojo.mainExp) - checkInt(playerExp.totalExp))/checkInt(nextExp.exp)
    end
    self:ProgressAction(startAmount ,endAmount )
    self.TxtLevel.text = tostring(playerLv)
    self.TxtProgress.text = string.fmt("<color=#727272>_num1_</color>/_num2_", {_num1_ = currentExp , _num2_ = checkInt(nextExp.exp)})
    self:ProgressAction(startAmount ,endAmount )
    self.isUpgradeLevel = playerComponent:UpdatePlayerLvMainExp(playerLv ,parameters.mainExp , parameters.hp, false)
    if self.isUpgradeLevel then
        self.deialogCo = cs_coroutine.start(function()
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
            self:ShowUpgradeLevelUI()
            self.isUpgradeLevel = false
        end)

    end
    --更新卡牌
    local cards = parameters.cardExp or {}
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    for k, v in pairs(cards) do
        cardComponent:UpdateCardDojo(k, v)
    end
end

function SweepQuestRewardsDialog:ProgressAction(startAmount , endAmount)
    local value = (endAmount - startAmount)/30
    local currentValue = startAmount
    self.co = cs_coroutine.start(function()
        currentValue = currentValue + value
        while currentValue < endAmount do
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.005))
            self.ImgProgressLine.fillAmount = currentValue
            currentValue = currentValue + value
        end
        self.ImgProgressLine.fillAmount = endAmount
    end)
end
function SweepQuestRewardsDialog:GetSortKeys()
    local parameters = self.controller.Argument.parameters
    local rewards = parameters.rewards
    self.sortKeys = table.keys(rewards)
    table.sort(self.sortKeys , function(a, b )
        return checkInt(a) < checkInt(b)
    end)
end
function SweepQuestRewardsDialog:ShowUpgradeLevelUI()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    playerComponent:ShowRewardsSpecialDialog()
end
function SweepQuestRewardsDialog:BindClick()
    local SetButtonAction = SetButtonAction
    SetButtonAction(self.BtnClose, function()
        UIModule.CloseDialog(self.controller)
    end)
    SetButtonAction(self.FontStyleButton, function()
        UIModule.CloseDialog(self.controller)
    end)
end
function SweepQuestRewardsDialog:OnGetCellIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    ---@type SweepQuestRewardsCell
    local scr = CfUtils.GetLuaScr(cell, 'Game.UI.DailyQuest.SweepQuestRewardsCell')
    if scr then
        local key = tostring(self.sortKeys[index+1])
        scr:RefreshUI(index ,self.controller.Argument.parameters.rewards[key] ,self.isGuang ,self.sweepTimes)
    end
    return cell
end

function SweepQuestRewardsDialog:FillSelf()
    self.sweepTimes = table.count(self.sortKeys)
    if self._isInitList then
        GameUtils.ReloadData(self.ScrollView, self.sweepTimes)
    else
        self.ScrollView:InitListView(self.sweepTimes, Bind(self, self.OnGetCellIndex))
        self._isInitList = true
    end

    self.ScrollView:MovePanelToItemIndex(self.sweepTimes -1)
    self.ScrollView.mOnBeginDragAction = function()
        ---@type Engine.Modules.LuaBehaviour
        local beh =  GetLuaBehaviour(self.Cell.gameObject,'Game.UI.DailyQuest.SweepQuestRewardsCell')
        beh.Env.RewardAnimNode.enabled = false
        self.isGuang = true
    end
end

function SweepQuestRewardsDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            if self.isUpgradeLevel then
                self:ShowUpgradeLevelUI()
                self.isUpgradeLevel = false
            end
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:Delete()
            self = nil --lua层的gc需要    
        end)
    end))
    return coWait
end
return SweepQuestRewardsDialog